copyJobs.forEach((job) => {
  const srcPath = path.join(assetsDir, job.src);
  const destPath = path.join(eventsDir, job.dest);

  // Ensure destination directory exists
  fs.mkdirSync(path.dirname(destPath), { recursive: true });

  if (fs.existsSync(srcPath)) {
    fs.copyFileSync(srcPath, destPath);
    console.log(`Copied ${job.src} -> ${job.dest}`);
  } else {
    console.warn(`Source path not found: ${srcPath}`);
  }
});

console.log("Finished copying event assets!");
